     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.notifications.ReservationCancelled;
     6	import hotel.notifications.ReservationConfirmed;
     7	import hotel.notifications.ReservationEventPublisher;
     8	import hotel.rooms.Room;
     9	import hotel.rooms.Rooms;
    10	import java.math.BigDecimal;
    11	
    12	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    13	public final class ReservationService {
    14	
    15	    static final String HOTEL_NAME = "Pousada Maré Alta";
    16	
    17	    private final Rooms rooms;
    18	    private final ReservationStore store;
    19	    private final PriceCalculator priceCalculator;
    20	    private final EmailSender emailSender;
    21	    private final ReservationEventPublisher eventPublisher;
    22	
    23	    public ReservationService(
    24	            Rooms rooms,
    25	            ReservationStore store,
    26	            PriceCalculator priceCalculator,
    27	            EmailSender emailSender,
    28	            ReservationEventPublisher eventPublisher) {
    29	        this.rooms = rooms;
    30	        this.store = store;
    31	        this.priceCalculator = priceCalculator;
    32	        this.emailSender = emailSender;
    33	        this.eventPublisher = eventPublisher;
    34	    }
    35	
    36	    public synchronized Reservation create(NewReservation request) {
    37	        if (!request.checkOut().isAfter(request.checkIn())) {
    38	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    39	        }
    40	        if (request.guests() < 1) {
    41	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    42	        }
    43	        Room room = rooms.find(request.roomNumber())
    44	                .orElseThrow(() -> new HotelException(
    45	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    46	        if (request.guests() > room.capacity()) {
    47	            throw new HotelException(
    48	                    ErrorCode.CAPACITY_EXCEEDED,
    49	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    50	        }
    51	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    52	            throw new HotelException(
    53	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    54	        }
    55	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    56	        return store.add(request, price);
    57	    }
    58	
    59	    public Reservation find(long reservationId) {
    60	        return store.find(reservationId)
    61	                .orElseThrow(() -> new HotelException(
    62	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    63	    }
    64	
    65	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    66	    public synchronized Reservation confirm(long reservationId) {
    67	        Reservation reservation = find(reservationId);
    68	        if (reservation.status() != ReservationStatus.PENDING) {
    69	            throw notAllowed(reservation, "confirm");
    70	        }
    71	        reservation.confirmPayment();
    72	        store.update(reservation);
    73	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    74	        emailSender.send(
    75	                reservation.guest().email(),
    76	                "Reserva confirmada - " + HOTEL_NAME,
    77	                confirmationEmailBody(reservation, receipt));
    78	        eventPublisher.publish(new ReservationConfirmed(reservation));
    79	        return reservation;
    80	    }
    81	
    82	    /**
    83	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    84	     * reservation was never paid, so nothing comes back).
    85	     */
    86	    public synchronized Reservation cancel(long reservationId) {
    87	        Reservation reservation = find(reservationId);
    88	        if (reservation.status() != ReservationStatus.PENDING
    89	                && reservation.status() != ReservationStatus.CONFIRMED) {
    90	            throw notAllowed(reservation, "cancel");
    91	        }
    92	        ReservationStatus previousStatus = reservation.status();
    93	        BigDecimal refund = switch (reservation.ratePlan()) {
    94	            case STANDARD -> reservation.amountPaid();
    95	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    96	        };
    97	        reservation.cancel(refund);
    98	        store.update(reservation);
    99	        eventPublisher.publish(new ReservationCancelled(reservation, previousStatus));
   100	        return reservation;
   101	    }
   102	
   103	    public synchronized Reservation checkIn(long reservationId) {
   104	        Reservation reservation = find(reservationId);
   105	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   106	            throw notAllowed(reservation, "check in");
   107	        }
   108	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   109	        store.update(reservation);
   110	        return reservation;
   111	    }
   112	
   113	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   114	    public synchronized ReservationReceipt checkOut(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   117	            throw notAllowed(reservation, "check out");
   118	        }
   119	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   120	        store.update(reservation);
