    36	    public synchronized Reservation create(NewReservation request) {
    37	        if (!request.checkOut().isAfter(request.checkIn())) {
    38	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    39	        }
    40	        if (request.guests() < 1) {
    41	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    42	        }
    43	        Room room = rooms.find(request.roomNumber())
    44	                .orElseThrow(() -> new HotelException(
    45	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    46	        if (request.guests() > room.capacity()) {
    47	            throw new HotelException(
    48	                    ErrorCode.CAPACITY_EXCEEDED,
    49	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    50	        }
    51	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    52	            throw new HotelException(
    53	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    54	        }
    55	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    56	        return store.add(request, price);
    57	    }
